using System;
using System.Collections.Generic;
using UnityEngine;

namespace GPA.TopDown2D
{
    /// <summary>
    /// Directed lane graph for traffic (spec §6: graph-based navigation). Nodes sit at both ends of
    /// every lane segment between junctions: an entry just after a junction and an exit at the stop
    /// line before the next. Lane edges run entry → exit; junction edges run exit → entry across a
    /// junction (straight, left or right; never a U-turn) and curve through a bezier control point.
    /// Generated by the city builder and saved in the scene.
    /// </summary>
    public sealed class RoadGraph2D : MonoBehaviour
    {
        [Serializable]
        public struct Node
        {
            public Vector2 Position;
            public float Heading;        // degrees around Z, 0 = north
            public bool Vertical;        // lane runs north-south (signal axis)
            public bool IsExit;          // stop line before a junction
            public int Junction;         // junction this node touches (-1 none)
        }

        [Serializable]
        public struct Edge
        {
            public int From, To;
            public bool ThroughJunction;
            public Vector2 Control;      // bezier control for turns (= midpoint when straight)
            public float SpeedLimit;     // m/s for this lane segment; 0 = the normal city speed
            public float Weight;         // how often traffic picks this edge; 0 = default (3 straight on, 1 turning)
        }

        [Serializable]
        public struct Junction
        {
            public Vector2 Centre;
            public string Name;
        }

        public static RoadGraph2D Instance { get; private set; }

        public Node[] Nodes = new Node[0];
        public Edge[] Edges = new Edge[0];
        public Junction[] Junctions = new Junction[0];
        [Tooltip("Speed limit on lane segments, m/s (11 ≈ 40 km/h).")]
        public float LaneSpeed = 11f;
        public float TurnSpeed = 5.5f;

        private List<int>[] _out;

        private void Awake()
        {
            Instance = this;
            _out = new List<int>[Nodes.Length];
            for (int i = 0; i < Nodes.Length; i++) _out[i] = new List<int>();
            for (int e = 0; e < Edges.Length; e++) _out[Edges[e].From].Add(e);
        }

        private void OnDestroy() { if (Instance == this) Instance = null; }

        public IReadOnlyList<int> Outgoing(int node) => _out[node];

        /// <summary>Points along an edge, spaced for steering (2 for straight lanes, more for turns).</summary>
        public void Sample(int edge, List<Vector2> into)
        {
            Edge e = Edges[edge];
            Vector2 a = Nodes[e.From].Position, b = Nodes[e.To].Position;
            if (!e.ThroughJunction || Vector2.Distance(e.Control, (a + b) * 0.5f) < 0.5f)
            {
                float length = Vector2.Distance(a, b);
                int steps = Mathf.Max(1, Mathf.CeilToInt(length / 8f));
                for (int i = 1; i <= steps; i++) into.Add(Vector2.Lerp(a, b, i / (float)steps));
                return;
            }
            for (int i = 1; i <= 8; i++)
            {
                float t = i / 8f, u = 1f - t;
                into.Add(u * u * a + 2f * u * t * e.Control + t * t * b);
            }
        }

        /// <summary>Picks a following edge: mostly straight on, sometimes turning.</summary>
        public int PickNext(int edge)
        {
            var options = _out[Edges[edge].To];
            if (options.Count == 0) return -1;
            if (options.Count == 1) return options[0];
            float heading = Nodes[Edges[edge].To].Heading;
            float total = 0f;
            var weights = new float[options.Count];
            for (int i = 0; i < options.Count; i++)
            {
                float turn = Mathf.Abs(Mathf.DeltaAngle(heading, Nodes[Edges[options[i]].To].Heading));
                float w = Edges[options[i]].Weight;
                weights[i] = w > 0f ? w : turn < 10f ? 3f : 1f;   // e.g. a beltway off-ramp: weight 1 against 3 straight on
                total += weights[i];
            }
            float roll = UnityEngine.Random.value * total;
            for (int i = 0; i < options.Count; i++) { roll -= weights[i]; if (roll <= 0f) return options[i]; }
            return options[options.Count - 1];
        }

        /// <summary>Lane edges (not junction crossings) — where traffic can be spawned.</summary>
        public IEnumerable<int> LaneEdges()
        {
            for (int e = 0; e < Edges.Length; e++) if (!Edges[e].ThroughJunction) yield return e;
        }
    }
}
